<template><section class="grid"><div class="card"><h1>친구 찾기</h1><form class="form" @submit.prevent="search"><input v-model="keyword" placeholder="아이디 또는 이메일"><button>검색</button></form><p v-for="u in users" :key="u.id" class="row">{{u.username}} <button class="secondary" @click="request(u.id)">요청</button></p></div><div class="card"><h2>받은 요청</h2><p v-for="r in received" :key="r.id" class="row">{{r.user.username}} <button @click="respond(r.id,'accept')">수락</button><button class="danger" @click="respond(r.id,'reject')">거절</button></p></div><div class="card"><h2>친구 목록</h2><p v-for="f in friends" :key="f.id">{{f.username}}</p></div></section></template>
<script setup>import { onMounted, ref } from 'vue'; import api from '@/api/axios'; const keyword=ref(''); const users=ref([]); const received=ref([]); const friends=ref([]); const search=async()=>{users.value=(await api.get('/api/v1/friends/search/',{params:{q:keyword.value}})).data}; const request=async(id)=>{await api.post('/api/v1/friends/request/',{friend_id:id}); alert('요청 완료')}; const load=async()=>{received.value=(await api.get('/api/v1/friends/requests/received/')).data; friends.value=(await api.get('/api/v1/friends/')).data}; const respond=async(id,action)=>{await api.post(`/api/v1/friends/requests/${id}/respond/`,{action}); await load()}; onMounted(load)</script>
